import{_ as t,o as i,c as a,a0 as s}from"./chunks/framework.CqtftVNu.js";const k=JSON.parse('{"title":"OAuth Client Certificates","description":"","frontmatter":{},"headers":[],"relativePath":"guide/user/client-certificates.md","filePath":"guide/user/client-certificates.md"}'),n={name:"guide/user/client-certificates.md"};function l(r,e,h,c,d,o){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="oauth-client-certificates" tabindex="-1">OAuth Client Certificates <a class="header-anchor" href="#oauth-client-certificates" aria-label="Permalink to &quot;OAuth Client Certificates&quot;">​</a></h1><p>Authup supports two independent uses of a TLS client certificate:</p><table tabindex="0"><thead><tr><th>Client setting</th><th>Purpose</th><th>Certificate trust requirement</th></tr></thead><tbody><tr><td><code>authMethod: tls</code></td><td>Authenticates the OAuth client at <code>/token</code> instead of a shared secret</td><td>Must chain to an enabled trust anchor in the client&#39;s realm</td></tr><tr><td><code>tokenBindingMethod: tls</code></td><td>Binds issued tokens to the certificate so a copied token is unusable by itself</td><td>Any currently valid non-CA certificate, including self-signed</td></tr></tbody></table><p>You can enable either setting or both. TLS authentication does not automatically bind tokens, and token binding does not automatically make the certificate a trusted client identity.</p><p>This release consumes certificates issued by an external PKI. Authup-managed CSR signing and generated client bundles are not part of this release.</p><h2 id="configure-a-client" tabindex="-1">Configure a client <a class="header-anchor" href="#configure-a-client" aria-label="Permalink to &quot;Configure a client&quot;">​</a></h2><p>Open the client in the admin UI and choose:</p><ul><li><strong>Authentication method:</strong> <code>None</code>, <code>Shared secret</code>, or <code>TLS certificate</code>.</li><li><strong>Token binding:</strong> <code>Disabled</code> or <code>TLS certificate</code>.</li></ul><p>The API fields are:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;authMethod&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tls&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tokenBindingMethod&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tls&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The authentication methods are exclusive. A <code>tls</code> client must not send a secret, and a <code>secret</code> client cannot fall back to a certificate. Switching away from <code>secret</code> permanently clears the stored secret and its hash/encryption flags. Generate a new secret if you later switch back.</p><p><code>client_credentials</code> requires an authenticated client, so it accepts <code>secret</code> and <code>tls</code> clients but not <code>none</code> clients.</p><h2 id="certificate-identity-for-tls-authentication" tabindex="-1">Certificate identity for TLS authentication <a class="header-anchor" href="#certificate-identity-for-tls-authentication" aria-label="Permalink to &quot;Certificate identity for TLS authentication&quot;">​</a></h2><p>After the client has been created, its detail form displays a stable URI:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>urn:authup:client:&lt;client-uuid&gt;</span></span></code></pre></div><p>The external CA must put that exact value in a URI Subject Alternative Name (SAN). For example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>URI:urn:authup:client:26f7b5ea-50af-46ac-98aa-2735ea3f5639</span></span></code></pre></div><p>The certificate may contain DNS names or other SANs. It must contain exactly one URI SAN in the <code>urn:authup:client:</code> namespace, and that URI must match the requested client&#39;s UUID. Mutable client and realm names are deliberately not certificate identities.</p><p>For <code>authMethod: tls</code>, Authup also checks:</p><ul><li>the leaf and every selected issuer are currently valid;</li><li>the leaf is not a CA certificate;</li><li>the chain signatures, CA basic constraints, path-length constraints, and issuer key usage;</li><li><code>clientAuth</code> extended key usage when an EKU extension is present; and</li><li><code>digitalSignature</code> when a key-usage extension is present.</li></ul><p>The chain must end at an enabled <a href="./trust-anchors.html">trust anchor</a> in the client&#39;s realm. Authup performs no AIA, CRL, or OCSP network fetch during a request. Prefer short-lived client certificates. To stop trusting all certificates issued below a compromised CA, disable its trust anchor and revoke existing sessions/tokens separately.</p><h2 id="token-binding" tabindex="-1">Token binding <a class="header-anchor" href="#token-binding" aria-label="Permalink to &quot;Token binding&quot;">​</a></h2><p>With <code>tokenBindingMethod: tls</code>, Authup places the presented leaf certificate&#39;s SHA-256 DER thumbprint in each access and refresh token:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;cnf&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;x5t#S256&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;base64url-sha256-thumbprint&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Authup&#39;s own API and the <code>server-adapter-*</code> packages compare that signed value with trusted certificate evidence on every protected request. They do not repeat chain validation at the resource server.</p><p>A refresh request must present the same certificate again. The refresh token is proof of the grant, while the TLS certificate proves that the caller still holds the private key to which the grant was bound. Sending only the refresh token would turn it back into a transferable bearer credential. Rotation preserves the same <code>cnf</code> claim on the replacement access and refresh tokens.</p><p>For binding without TLS authentication, a self-signed or otherwise untrusted leaf is valid. Trust is unnecessary because the certificate is not being used to decide which client is calling; its thumbprint is only the proof-of-possession key identifier. The proxy must still attest that the certificate came from the TLS handshake.</p><h2 id="requests" tabindex="-1">Requests <a class="header-anchor" href="#requests" aria-label="Permalink to &quot;Requests&quot;">​</a></h2><p>Use a real TLS client certificate and private key with the public proxy. Do not construct Authup&#39;s forwarding headers in application code:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client.crt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client.key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data-urlencode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grant_type=client_credentials</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data-urlencode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client_id=26f7b5ea-50af-46ac-98aa-2735ea3f5639</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://mtls.auth.example.com/token</span></span></code></pre></div><p>For TLS authentication, send <code>client_id</code> without <code>client_secret</code>. A Basic authorization header counts as secret authentication and is rejected for a TLS client.</p><p>Present the same certificate when using a bound access or refresh token:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client.crt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client.key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ACCESS_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://mtls.auth.example.com/users/@me</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client.crt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client.key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data-urlencode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grant_type=refresh_token</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data-urlencode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> refresh_token=&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$REFRESH_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data-urlencode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client_id=26f7b5ea-50af-46ac-98aa-2735ea3f5639</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://mtls.auth.example.com/token</span></span></code></pre></div><p>When <code>CERTIFICATE_SOURCE</code> is enabled, the OpenID provider metadata advertises <code>tls_client_auth</code> and certificate-bound token support. If <code>MTLS_PUBLIC_URL</code> is configured, it also publishes <code>mtls_endpoint_aliases</code> so clients can select the certificate-requesting origin automatically. Disabled deployments do not advertise certificate features they cannot accept.</p><h2 id="trusted-proxy-requirement" tabindex="-1">Trusted proxy requirement <a class="header-anchor" href="#trusted-proxy-requirement" aria-label="Permalink to &quot;Trusted proxy requirement&quot;">​</a></h2><p>Authup&#39;s Node listener remains HTTP behind the load balancer. The configured proxy requests the certificate during the TLS handshake, removes any certificate headers supplied by the public caller, and writes one authenticated header contract to the private backend request.</p><p><code>CERTIFICATE_SOURCE</code> is disabled by default and accepts exactly one of:</p><ul><li><code>standard</code>: RFC 9440 <code>Client-Cert</code> and optional <code>Client-Cert-Chain</code> headers;</li><li><code>forwarded</code>: one URL-escaped PEM leaf in <code>X-Forwarded-Tls-Client-Cert</code>; or</li><li><code>disabled</code>: ignore all certificate headers.</li></ul><p>Authup never falls back between these header families. The backend port must not be reachable by public clients; otherwise an attacker could forge the header and impersonate a certificate holder.</p><p>The native NGINX and Traefik forwarded formats carry only the leaf. In <code>forwarded</code> mode, a TLS-authentication leaf must therefore be signed directly by an enabled realm trust anchor. Use <code>standard</code> mode and <code>Client-Cert-Chain</code> when the PKI requires intermediate certificates.</p><p>See the <a href="./../deployment/nginx.html">NGINX</a> and <a href="./../deployment/traefik.html">Traefik</a> deployment examples.</p>`,41)])])}const u=t(n,[["render",l]]);export{k as __pageData,u as default};
